/** The reject codes a kind takes (13e: avatar and service photo use the image lists, every other kind the text list). */
export function moderationReasonCodes(kind: ModerationKind): readonly string[] {
  if (kind === "avatar") return Object.keys(REASON_MESSAGES.avatar);
  if (kind === "service_photo") return Object.keys(REASON_MESSAGES.photo);
  if (kind === "payment") return [...new Set([...Object.keys(REASON_MESSAGES.qr), ...Object.keys(REASON_MESSAGES.text)])];
  return Object.keys(REASON_MESSAGES.text);
}

